def initialize
  # Movement
  @bicycle              = false
  @surfing              = false
  @diving               = false
  @ice_sliding          = false
  @descending_waterfall = false
  @ascending_waterfall  = false
  @fishing              = false
  # Player data
  @startTime            = Time.now
  @stepcount            = 0
  @pcItemStorage        = nil
  @mailbox              = nil
  @phone                = Phone.new
  @partner              = nil
  @creditsPlayed        = false
  # Pokédex
  numRegions            = pbLoadRegionalDexes.length
  @pokedexDex           = (numRegions == 0) ? -1 : 0
  @pokedexIndex         = []
  @pokedexMode          = 0
  (numRegions + 1).times do |i|     # National Dex isn't a region, but is included
    @pokedexIndex[i] = 0
  end
  # Day Care
  @day_care             = DayCare.new
  # Special battle modes
  @safariState          = nil
  @bugContestState      = nil
  @challenge            = nil
  @lastbattle           = nil
  # Events
  @eventvars            = {}
  # Affecting the map
  @bridge               = 0
  @repel                = 0
  @flashused            = false
  @encounter_version    = 0
  # Map transfers
  @healingSpot          = nil
  @escapePoint          = []
  @pokecenterMapId      = -1
  @pokecenterX          = -1
  @pokecenterY          = -1
  @pokecenterDirection  = -1
  # Movement history
  @visitedMaps          = []
  @mapTrail             = []
  # Counters
  @happinessSteps       = 0
  @pokerusTime          = nil
  # Save file
  @safesave             = false
end

def encounter_version=(value)
  validate value => Integer
  return if @encounter_version == value
  @encounter_version = value
  $PokemonEncounters.setup($game_map.map_id) if $PokemonEncounters && $game_map
end
